"""Dataset loading helpers for evaluation."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Any, Dict, List, Union


def load_dataset(source: Union[str, Path, List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    """Load evaluation dataset from JSON file, CSV file, or list of dicts.

    Each item must have at minimum "input" and "expected" keys.

    Parameters
    ----------
    source : str, Path, or list of dict
        Path to a JSON/CSV file, or a list of dicts directly.

    Returns
    -------
    list of dict
        Standardized dataset items with "input" and "expected" keys.
    """
    if isinstance(source, list):
        return _validate(source)

    path = Path(source)
    if not path.exists():
        raise FileNotFoundError(f"Dataset file not found: {path}")

    suffix = path.suffix.lower()
    if suffix == ".json":
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, list):
            return _validate(data)
        raise ValueError("JSON dataset must be a list of objects")

    if suffix == ".csv":
        return _load_csv(path)

    raise ValueError(f"Unsupported file format: {suffix}. Use .json or .csv")


def _load_csv(path: Path) -> List[Dict[str, Any]]:
    """Load dataset from CSV. Expects 'input' and 'expected' columns."""
    items: List[Dict[str, Any]] = []
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            item: Dict[str, Any] = {"input": row.get("input", "")}
            expected = row.get("expected", "")
            # Try to parse expected as JSON
            try:
                item["expected"] = json.loads(expected)
            except (json.JSONDecodeError, ValueError):
                item["expected"] = expected
            # Pass through any extra columns
            for k, v in row.items():
                if k not in ("input", "expected"):
                    item[k] = v
            items.append(item)
    return items


def _validate(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Validate that each item has required keys."""
    for i, item in enumerate(data):
        if "input" not in item:
            raise ValueError(f"Dataset item {i} missing 'input' key")
        if "expected" not in item:
            raise ValueError(f"Dataset item {i} missing 'expected' key")
    return data

"""Evaluator — runs a task over a dataset and computes metrics."""

from __future__ import annotations

import logging
from typing import Any, Callable, Dict, List, Optional, Union

from pydantic import BaseModel

from promptify.core.exceptions import EvaluationError
from promptify.eval.metrics import METRIC_REGISTRY

logger = logging.getLogger("promptify")


def _extract_comparable(result: Any) -> Any:
    """Extract comparable data from a Pydantic model or raw value."""
    if isinstance(result, BaseModel):
        return result.model_dump()
    return result


def _compare_for_metric(
    metric_name: str,
    predicted: Any,
    expected: Any,
) -> float:
    """Run a single metric comparison between predicted and expected."""
    metric_fn = METRIC_REGISTRY.get(metric_name)
    if metric_fn is None:
        raise EvaluationError(f"Unknown metric: {metric_name}")

    pred = _extract_comparable(predicted)
    exp = _extract_comparable(expected)

    if metric_name in ("precision", "recall", "f1"):
        # These expect lists
        if isinstance(pred, dict):
            # Flatten dict values into a list for comparison
            pred_list = []
            for v in pred.values():
                if isinstance(v, list):
                    pred_list.extend(str(item) for item in v)
                else:
                    pred_list.append(str(v))
            pred = pred_list
        if isinstance(exp, dict):
            exp_list = []
            for v in exp.values():
                if isinstance(v, list):
                    exp_list.extend(str(item) for item in v)
                else:
                    exp_list.append(str(v))
            exp = exp_list
        if not isinstance(pred, list):
            pred = [pred]
        if not isinstance(exp, list):
            exp = [exp]
        return metric_fn(pred, exp)

    if metric_name == "accuracy":
        if not isinstance(pred, list):
            pred = [pred]
        if not isinstance(exp, list):
            exp = [exp]
        return metric_fn(pred, exp)

    if metric_name == "exact_match":
        return metric_fn(str(pred), str(exp))

    if metric_name == "rouge":
        scores = metric_fn(str(pred), str(exp))
        return scores.get("rougeL", 0.0)

    return metric_fn(pred, exp)


def evaluate(
    task: Any,
    dataset: List[Dict[str, Any]],
    metrics: List[str],
    max_samples: Optional[int] = None,
    progress_callback: Optional[Callable[[int, int], None]] = None,
) -> Dict[str, float]:
    """Evaluate a task on a dataset.

    Parameters
    ----------
    task : BaseTask
        The task to evaluate.
    dataset : list of dict
        Each item has "input" (str) and "expected" (BaseModel or dict).
        For QA tasks, items may also have "question".
    metrics : list of str
        Metric names from METRIC_REGISTRY.
    max_samples : int, optional
        Limit the number of samples to evaluate.
    progress_callback : callable, optional
        Called with (current_index, total) after each sample.

    Returns
    -------
    dict of str to float
        Aggregated metric scores.
    """
    if not dataset:
        raise EvaluationError("Dataset is empty")

    samples = dataset[:max_samples] if max_samples else dataset
    total = len(samples)

    scores: Dict[str, List[float]] = {m: [] for m in metrics}

    for i, sample in enumerate(samples):
        text_input = sample.get("input", "")
        expected = sample.get("expected")
        extra_kwargs = {k: v for k, v in sample.items() if k not in ("input", "expected")}

        try:
            predicted = task(text_input, **extra_kwargs)
        except Exception as exc:
            logger.warning("Evaluation failed on sample %d: %s", i, exc)
            for m in metrics:
                scores[m].append(0.0)
            continue

        for m in metrics:
            try:
                score = _compare_for_metric(m, predicted, expected)
                scores[m].append(score)

"""Evaluation metrics for NLP tasks."""

from __future__ import annotations

from collections import Counter
from typing import Any, Dict, List, Set, Tuple


def _to_set(items: Any) -> Set[str]:
    """Convert items to a set of strings for comparison."""
    if isinstance(items, (list, tuple)):
        return {str(i) for i in items}
    return {str(items)}


def precision(predicted: List[Any], expected: List[Any]) -> float:
    """Compute precision: TP / (TP + FP)."""
    if not predicted:
        return 0.0
    pred_set = _to_set(predicted)
    exp_set = _to_set(expected)
    tp = len(pred_set & exp_set)
    return tp / len(pred_set) if pred_set else 0.0


def recall(predicted: List[Any], expected: List[Any]) -> float:
    """Compute recall: TP / (TP + FN)."""
    if not expected:
        return 0.0
    pred_set = _to_set(predicted)
    exp_set = _to_set(expected)
    tp = len(pred_set & exp_set)
    return tp / len(exp_set) if exp_set else 0.0


def f1(predicted: List[Any], expected: List[Any]) -> float:
    """Compute F1 score: harmonic mean of precision and recall."""
    p = precision(predicted, expected)
    r = recall(predicted, expected)
    if p + r == 0:
        return 0.0
    return 2 * p * r / (p + r)


def accuracy(predicted: List[Any], expected: List[Any]) -> float:
    """Compute accuracy: fraction of correct predictions."""
    if not predicted or len(predicted) != len(expected):
        return 0.0
    correct = sum(1 for p, e in zip(predicted, expected) if str(p) == str(e))
    return correct / len(predicted)


def exact_match(predicted: str, expected: str) -> float:
    """Exact string match (1.0 or 0.0)."""
    return 1.0 if str(predicted).strip() == str(expected).strip() else 0.0


def rouge(predicted: str, expected: str) -> Dict[str, float]:
    """Compute ROUGE scores. Requires rouge-score package."""
    try:
        from rouge_score import rouge_scorer
    except ImportError:
        raise ImportError(
            "rouge-score is required for ROUGE metrics. "
            "Install with: pip install promptify[eval]"
        )
    scorer = rouge_scorer.RougeScorer(["rouge1", "rouge2", "rougeL"], use_stemmer=True)
    scores = scorer.score(str(expected), str(predicted))
    return {
        "rouge1": scores["rouge1"].fmeasure,
        "rouge2": scores["rouge2"].fmeasure,
        "rougeL": scores["rougeL"].fmeasure,
    }


METRIC_REGISTRY: Dict[str, Any] = {
    "precision": precision,
    "recall": recall,
    "f1": f1,
    "accuracy": accuracy,
    "exact_match": exact_match,
    "rouge": rouge,
}
